 static float Height(float x,float z){float h=z<=0?0:z<=20?z/20:z<=55?1+(z-20)*3/35:z<=85?4:z<=105?4+(z-85)*4/20:z<=120?8+(z-105)*4/15:12;float east=Mathf.SmoothStep(0,1,Mathf.InverseLerp(30,70,x));return h*Mathf.Lerp(1,0.35f,east)+.25f*east*Mathf.Clamp01(z/20f);}
