 static Material Mat(string name,string hex){if(mats.ContainsKey(name))return mats[name];var shader=Shader.Find(name=="SandTan" || name.StartsWith("Wayfinding") ? "Universal Render Pipeline/Unlit" : "Universal Render Pipeline/Lit");if(!shader)throw new Exception("URP Lit unavailable");var m=new Material(shader);m.name=name;ColorUtility.TryParseHtmlString(hex,out var color);m.SetColor("_BaseColor",color);m.SetFloat("_Smoothness",0.18f);m.enableInstancing=true;AssetDatabase.CreateAsset(m,Folder+"/Materials/"+name+".mat");mats[name]=m;return m;}
