 static void Edge(string n,Vector2 a,Vector2 b,Material m,Transform p,float width){int steps=Mathf.Max(1,Mathf.CeilToInt(Vector2.Distance(a,b)/3));var line=new GameObject(n);line.transform.SetParent(p,false);line.transform.rotation=Quaternion.Euler(90,0,0);var lr=line.AddComponent<LineRenderer>();lr.sharedMaterial=m;lr.useWorldSpace=true;lr.alignment=LineAlignment.TransformZ;lr.positionCount=steps+1;for(int i=0;i<=steps;i++){var q=Vector2.Lerp(a,b,(float)i/steps);lr.SetPosition(i,At(q.x,q.y,.035f));}lr.startWidth=lr.endWidth=width;lr.shadowCastingMode=ShadowCastingMode.Off;lr.receiveShadows=false;}
