 var h=Zone("H_CommandHabitat",-65,-60,36,28);Box("HabitatShell_14x8m",-65,-60,2,new Vector3(14,4,8),mats["HabitatPale"],h);Box("Airlock_2mClearEntryPlaceholder",-55,-60,1.5f,new Vector3(6,3,4),mats["IndustrialGraphite"],h);Box("AirlockEntryAccent",-51.9f,-60,1.6f,new Vector3(.12f,2.6f,2),mats["WayfindingCyan"],h,false);Box("HabitatLandmarkMast_8m",-65,-60,4,new Vector3(.35f,8,.35f),mats["WayfindingCyan"],h);
 var g=Zone("G_Greenhouse",-65,-10,30,22);var cylinder=Shape("OpaqueShieldedGreenhouse_18x8m",PrimitiveType.Cylinder,At(-65,-10,3.5f),new Vector3(7,9,7),mats["HabitatPale"],g);cylinder.transform.rotation=Quaternion.Euler(0,0,90);Box("ServiceHatch",-55,-10,1.4f,new Vector3(2,2.8f,3),mats["IndustrialGraphite"],g);
 var r=Zone("R_RoverBay",-15,-95,32,20);Box("Canopy",-15,-95,4,new Vector3(18,.35f,10),mats["HabitatPale"],r);foreach(float x in new[]{-23f,-7f})foreach(float z in new[]{-99f,-91f})Box("CanopySupport",x,z,2,new Vector3(.4f,4,.4f),mats["IndustrialGraphite"],r);Box("StaticRoverProxy",-15,-95,1.5f,new Vector3(4,1.6f,2.6f),mats["IndustrialGraphite"],r);foreach(float x in new[]{-16.3f,-13.7f})foreach(float z in new[]{-96.5f,-93.5f}){var wheel=Shape("RoverWheelProxy",PrimitiveType.Cylinder,At(x,z,.65f),new Vector3(1.2f,.25f,1.2f),mats["DarkRock"],r);wheel.transform.rotation=Quaternion.Euler(90,0,0);}
