 var d=Zone("D_LayeredDeltaTerrain",0,85,70,40);for(int j=0;j<3;j++){float x=-24+j*24;for(int layer=0;layer<3;layer++)Box("DeltaBedding_"+j+"_"+layer,x,108+layer*3,.8f+layer*.15f,new Vector3(22-layer*3,1.6f,8),mats[layer%2==0?"LayeredStone":"DarkRock"],d);}Box("SampleRockPlaceholder",5,79,.6f,new Vector3(2,1.2f,1.8f),mats["LayeredStone"],d);
 var b=Zone("B_DarkRockComparison",75,35,30,26);for(int i=0;i<4;i++){var rock=Box("FloorRockProxy_"+i,72+i*4,39+(i%2)*3,1,new Vector3(2.8f,2,2.5f),mats["DarkRock"],b);rock.transform.rotation=Quaternion.Euler(0,i*29,0);}
 var footprint=Group("PlayableBoundary_250x250_NoCollision",terrainGroup);Edge("North",new Vector2(-125,125),new Vector2(125,125),mats["WayfindingAmber"],footprint,.2f);Edge("South",new Vector2(-125,-125),new Vector2(125,-125),mats["WayfindingAmber"],footprint,.2f);Edge("East",new Vector2(125,-125),new Vector2(125,125),mats["WayfindingAmber"],footprint,.2f);Edge("West",new Vector2(-125,-125),new Vector2(-125,125),mats["WayfindingAmber"],footprint,.2f);
 for(int i=0;i<route.Length;i++){var marker=Group("Waypoint_"+i.ToString("D2")+"_"+route[i].x+"_"+route[i].y,routeGroup);marker.position=At(route[i].x,route[i].y);if(i+1<route.Length)Edge("MissionSegment_"+i,route[i],route[i+1],mats["SandTan"],routeGroup,4);}
