 public static void Repair(){var scene=Open();var gm=ground.sharedMesh;var verts=gm.vertices;for(int vi=0;vi<verts.Length;vi++)verts[vi].y=Height(verts[vi].x,verts[vi].z);gm.vertices=verts;gm.RecalculateNormals();gm.RecalculateBounds();EditorUtility.SetDirty(gm);ground.sharedMesh=null;ground.sharedMesh=gm;foreach(var lr in root.GetComponentsInChildren<LineRenderer>()){for(int pi=0;pi<lr.positionCount;pi++){var pp=lr.GetPosition(pi);pp.y=Height(pp.x,pp.z)+.035f;lr.SetPosition(pi,pp);}}foreach(string materialName in new[]{"SandTan","WayfindingAmber","WayfindingCyan"}){var m=AssetDatabase.LoadAssetAtPath<Material>(Folder+"/Materials/"+materialName+".mat");var color=m.GetColor("_BaseColor");m.shader=Shader.Find("Universal Render Pipeline/Unlit");m.SetColor("_BaseColor",color);EditorUtility.SetDirty(m);}AssetDatabase.SaveAssets();foreach(var t in root.GetComponentsInChildren<Transform>()){if(t.name=="CompositionCamera_Overview"){var cc=t.GetComponent<Camera>();cc.orthographic=true;cc.orthographicSize=145;}if(t.name=="B_DarkRockComparison")t.position=At(75,35);if(t.name=="CompositionCamera_Spawn")t.LookAt(At(10,-5,3));if(t.name=="StorageModule")t.position=At(27,-38,1.6f);if(t.name=="ConsolePlaceholder_ApproachFromWest")t.position=At(19,-38,.6f);}EditorSceneManager.SaveScene(scene);Validate();Capture();File.WriteAllText(Output+"/creation-status.txt","Created and validated "+ScenePath);if(File.Exists(Output+"/automation-error.txt"))File.Delete(Output+"/automation-error.txt");}
 static Scene Open(){var s=SceneManager.GetSceneByPath(ScenePath);if(!s.isLoaded)s=EditorSceneManager.OpenScene(ScenePath,OpenSceneMode.Additive);SceneManager.SetActiveScene(s);root=s.GetRootGameObjects().Single(t=>t.name=="MarsOutpost_Greybox_1unit_1meter").transform;ground=root.GetComponentInChildren<MeshCollider>();for(int i=SceneManager.sceneCount-1;i>=0;i--){var prior=SceneManager.GetSceneAt(i);if(prior!=s && prior.name.StartsWith("PreGreybox_Untitled_Backup"))EditorSceneManager.CloseScene(prior,true);}return s;}
 [MenuItem("AstroGateway/Greybox/Validate")]
 public static void Validate(){Open();Physics.SyncTransforms();var all=root.GetComponentsInChildren<Transform>(true);var errors=new List<string>();foreach(string n in new[]{"H_CommandHabitat","G_Greenhouse","R_RoverBay","P_PowerStation","S_SolarArray","C_ScienceStaging","D_LayeredDeltaTerrain","B_DarkRockComparison"})if(!all.Any(t=>t.name==n))errors.Add("Missing zone "+n);foreach(var t in all)if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)errors.Add("Missing script on "+t.name);foreach(var rend in root.GetComponentsInChildren<Renderer>())foreach(var m in rend.sharedMaterials)if(!m||!m.shader||!m.shader.isSupported)errors.Add("Invalid material "+rend.name);
 float planar=0,spatial=0,maxSlope=0;int samples=0;var obstacles=root.GetComponentsInChildren<Collider>().Where(t=>t!=ground).ToArray();for(int i=0;i<route.Length-1;i++){var a=route[i];var b=route[i+1];float len=Vector2.Distance(a,b);planar+=len;int count=Mathf.CeilToInt(len/.5f);var prev=At(a.x,a.y);for(int j=0;j<=count;j++){var q=Vector2.Lerp(a,b,(float)j/count);var pos=At(q.x,q.y);if(j>0){spatial+=Vector3.Distance(prev,pos);maxSlope=Mathf.Max(maxSlope,Mathf.Atan2(Mathf.Abs(pos.y-prev.y),Vector2.Distance(new Vector2(prev.x,prev.z),q))*Mathf.Rad2Deg);}prev=pos;samples++;if(!ground.Raycast(new Ray(pos+Vector3.up*3,Vector3.down),out var hit,4))errors.Add("Missing ground at "+pos);foreach(var col in obstacles){var bb=col.bounds;bb.Expand(new Vector3(4,0,4));if(bb.Contains(pos+Vector3.up*.5f))errors.Add("4m corridor intersects "+col.name+" at "+q);}}}
 if(maxSlope>12)errors.Add("Route slope exceeds 12 degrees");var sight=new List<string>();CheckSight("Spawn to power mast",At(-45,-60,1.8f),At(25,-45,5.5f),sight);CheckSight("Spawn to delta silhouette",At(-45,-60,1.8f),At(0,114,2),sight);CheckSight("Delta to habitat roof",At(15,70,1.8f),At(-65,-60,3.8f),sight);
 string txt="# Stage 03 Geometry Validation\n\nUnity "+Application.unityVersion+"; active pipeline: "+GraphicsSettings.currentRenderPipeline+"\n\nPlanar route: "+planar.ToString("F2")+" m; terrain-following sampled route: "+spatial.ToString("F2")+" m.\nTraversal estimate at 2.5 m/s: "+(spatial/2.5f).ToString("F1")+" s, excluding interactions.\nMaximum sampled route slope: "+maxSlope.ToString("F2")+" degrees. Samples: "+samples+".\n\n"+string.Join("\n",sight)+"\n\nErrors: "+errors.Count+"\n"+string.Join("\n",errors.Distinct())+"\n\nValidation is geometric: no controller or human walking test is claimed.\n";File.WriteAllText(Output+"/Geometry_Validation.md",txt);if(errors.Count>0)throw new Exception(txt);Debug.Log("ASTROGATEWAY_VALIDATION_OK");}
 static void CheckSight(string name,Vector3 a,Vector3 b,List<string> result){var hits=Physics.RaycastAll(a,(b-a).normalized,Vector3.Distance(a,b)-.5f).Where(h=>h.collider.transform.IsChildOf(root)).OrderBy(h=>h.distance).ToArray();bool target=hits.Length>0 && ((name.Contains("delta") && hits[0].collider.name.StartsWith("DeltaBedding")) || (name.Contains("habitat") && hits[0].collider.name=="HabitatShell_14x8m"));result.Add(name+": "+(hits.Length==0?"clear":target?"visible (first hit target geometry)":"OBSTRUCTED by "+hits[0].collider.name));}
 [MenuItem("AstroGateway/Greybox/Capture")]
 public static void Capture(){Open();foreach(var cam in root.GetComponentsInChildren<Camera>()){var rt=new RenderTexture(1600,900,24);rt.Create();var req=new UniversalRenderPipeline.SingleCameraRequest{destination=rt};if(!RenderPipeline.SupportsRenderRequest(cam,req))throw new Exception("URP render request unsupported");RenderPipeline.SubmitRenderRequest(cam,req);var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(1600,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,900),0,0);tex.Apply();File.WriteAllBytes(Output+"/"+cam.name+".png",tex.EncodeToPNG());RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}Debug.Log("ASTROGATEWAY_CAPTURE_OK");}
 [MenuItem("AstroGateway/Greybox/Build Web")]
 public static void BuildWeb(){Open();var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{ScenePath},locationPathName=Output+"/Web",target=BuildTarget.WebGL,options=BuildOptions.None});File.WriteAllText(Output+"/Web_Build_Status.txt",report.summary.result+"\nErrors: "+report.summary.totalErrors+"\nWarnings: "+report.summary.totalWarnings+"\nBytes: "+report.summary.totalSize);if(report.summary.result!=BuildResult.Succeeded)throw new Exception("Web build failed");Debug.Log("ASTROGATEWAY_WEB_BUILD_OK");}
